// Preprocessing functions
/**
 * Removes duplicate entries from a vector of strings
 * Uses std::unique to identify and remove duplicates
 */
void deduplicate(vector<string>& data) {
    data.erase(unique(data.begin(), data.end()), data.end());
}

/**
 * Cleans text by removing non-alphanumeric characters and spaces
 * Converts text to lowercase (not implemented here for simplicity)
 */
void cleanText(string& text) {
    // Remove all characters that are not alphanumeric or whitespace
    text.erase(remove_if(text.begin(), text.end(), 
        [](char c){ return !isalnum(c) && !isspace(c); }), 
        text.end());
}

/**
