    int positive = 0, negative = 0;
    for (char c : text) {
        if (isalpha(c)) {
            // Basic heuristic: certain letters indicate positive/negative sentiment
            if (c == 'h' || c == 'j' || c == 'l') positive++;
            else if (c == 's' || c == 'n' || c == 'a') negative++;
        }
    }
    return (positive - negative) / (positive + negative + 1);
}

